static int p2d89_emit_quadrilaterals_squares(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 sq[]={-16384,-16384,16384,-16384,16384,16384,-16384,16384};if(id==P2D89_SHAPE_SQUARE||id==P2D89_SHAPE_HOLLOW_SQUARE)return p2d89_i_poly(sq,4U,1,p);if(id==P2D89_SHAPE_ROUNDED_SQUARE)return p2d89_i_rounded_rect(16384,16384,4096,p);if(id==P2D89_SHAPE_FRAME)return p2d89_i_frame(16384,12288,4096,p);if(id==P2D89_SHAPE_ROUNDED_FRAME){if(!p2d89_i_rounded_rect(16384,16384,4096,p))return 0;return p2d89_i_rounded_rect(11264,11264,3072,p);}return 0;}
const P2D89_Submodule p2d89_submodule_quadrilaterals_squares = { { P2D89_MODULE_QUADRILATERALS, "quadrilaterals", "squares", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_quadrilaterals_squares };
